('Wordtune','문장 재작성·문법 교정·요약으로 영어 표현을 다듬는 AI 글쓰기 도우미 #글쓰기 #문장교정 #요약 #영어','Wordtune은 웹 편집기와 브라우저 확장에서 영어 문장을 재작성하고 문법·명료성·어휘·유창성을 개선하며 긴 글을 요약하는 AI 글쓰기 도구입니다.','https://www.wordtune.com/','https://www.wordtune.com/favicon.ico','Freemium','$0','Basic 무료 · Advanced 연간 결제 월 $6.99',array['Basic은 하루 10회 재작성·AI 제안과 월 3회 요약을 제공합니다.','Advanced는 연간 결제 월 환산 $6.99입니다.','Unlimited는 연간 결제 월 환산 $9.99이며 주요 기능의 사용 제한을 해제합니다.'],'USD','https://www.wordtune.com/plans',now(),'None',true,false,false,null,'Augmented','specialized',array['문장 재작성','문법·명료성 교정','AI 요약'],array['어휘 개선','유창성 제안','브라우저 확장'],array['영어 문장을 자연스럽게 다듬기','웹 작성 화면에서 바로 사용','무료 기본 교정 제공'],array['영문 이메일·문서를 작성하는 사용자','영어 표현을 다듬고 싶은 비원어민'],array['주요 기능은 영어 글쓰기에 초점이 맞춰져 있습니다.','무료·Advanced 플랜은 일일·월간 한도가 있습니다.','재작성 결과의 의미와 사실을 직접 확인해야 합니다.'],array['https://www.wordtune.com/plans','https://support.wordtune.com/en/articles/8262930-wordtune-s-plans-pricing'],now(),now())
) as seed(name,description,full_description,url,logo_url,pricing_type,pricing_start_at,pricing_summary,pricing_details,pricing_currency,pricing_url,pricing_verified_at,korean_support_level,is_verified,is_domestic,has_api,api_url,ai_type,tool_scope,primary_features,secondary_features,key_benefits,best_for,limitations,verification_sources,verified_at,updated_at)
where not exists(select 1 from public.tools where lower(tools.url)=lower(seed.url));

